7	/// @notice A sink that splits what it receives between a fixed table of beneficiaries, escrows the
8	/// shares it cannot push, and puts every change to itself behind one timelock.
9	/// @dev Deployed once as an implementation and used through PUSH0 clones. `factory` and `self` live
10	/// in the implementation's bytecode, so a clone reads the implementation's deployer and the
11	/// implementation's own address — which is how the implementation rejects ETH while a clone accepts it.
12	contract Distribution {
13	    struct Beneficiary {
14	        address account;
15	        uint96 bps;
16	        string name;
17	        string note;
18	    }
19	
20	    struct Pending {
21	        bytes32 hash;
22	        uint256 eta;
23	        bytes action;
24	    }
25	
26	    struct Snapshot {
27	        address owner;
28	        uint32 delay;
29	        uint32 nonce;
30	        string description;
31	        Beneficiary[] table;
32	        Pending[] pending;
33	    }
34	
35	    event Received(address indexed from, uint256 amount);
36	    event Distributed(address indexed token, uint256 amount);
37	    event Escrowed(address indexed token, address indexed account, uint256 amount);
38	    event Released(address indexed token, address indexed account, uint256 amount);
39	    event Queued(bytes32 indexed hash, uint32 nonce, uint256 eta, bytes action);
40	    event Applied(bytes32 indexed hash);
41	    event Cancelled(bytes32 indexed hash);
42	
43	    /// @dev Ownable2Step's name and shape. Emitted on acceptance only: the nomination already rides
44	    /// in `Queued`'s calldata, so without this a log reader sees "B was nominated" and never "B took
45	    /// it" — the one state change in the contract with no trace of its own.
46	    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
47	
48	    error NotOwner();
49	    error BadTable();
50	    error NotReady(uint256 eta);
51	    error NothingToDo();
52	    error Locked();
53	    error Unauthorized();
54	    error ReleaseFailed(address token);
55	
56	    /// @dev Measured in m03-t01 (`test/PushGas.t.sol`, cold): a Safe v1.4.1 proxy receives in 4,029
57	    /// gas and a multisig.software vault clone in 404, so 100_000 is 23x the larger need and was kept
58	    /// under decision 30.
59	    uint256 private constant PUSH_GAS = 100_000;
60	    uint256 private constant BPS_TOTAL = 10_000;
61	
62	    /// @dev Measured in m03-t01 (`test/TableCap.t.sol`): a worst-case row, where the recipient burns
63	    /// the whole push cap and then fails, costs 138,917 gas, so 107 rows distribute in 14,896,325 and
64	    /// 108 need 15,035,242. The rule enforced is that a worst-case `distribute` stays under half a
65	    /// 30M block. Those three figures are of the tree t01 measured, `main` at `b055bc3`; re-measure
66	    /// rather than quote them.
67	    uint256 public constant MAX_BENEFICIARIES = 107;
68	    bytes4 private constant TRANSFER = 0xa9059cbb;
69	    bytes4 private constant BALANCE_OF = 0x70a08231;
70	
71	    address public owner;
72	    uint32 public delay;
73	    uint32 public nonce;
74	
75	    /// @dev After `nonce`, not after `owner`: `owner`, `delay` and `nonce` pack into one slot and a
76	    /// 20-byte address cannot join them, so placing it here leaves that slot whole and `propose` and
77	    /// `snapshot` keep their single read of it.
78	    address public pendingOwner;
79	    string public description;
80	
81	    /// @dev Stored in the order given, which table validation forces to be ascending by account.
82	    Beneficiary[] private _table;
83	    Pending[] private _pending;
84	    /// @dev 1-based index into `_pending`; 0 means absent.
85	    mapping(bytes32 => uint256) private _pendingIndex;
86	
87	    /// @notice Queued action hash to the timestamp it becomes applicable.
88	    mapping(bytes32 => uint256) public queued;
89	    /// @notice Token (0 for ETH) to the total this contract holds on behalf of failed pushes.
90	    mapping(address => uint256) public reserved;
91	    /// @notice Token (0 for ETH) to account to the amount escrowed for it.
92	    mapping(address => mapping(address => uint256)) public escrowed;
93	
94	    bool private transient locked;
95	
96	    address private immutable factory;
97	    address private immutable self;
98	
99	    constructor() {
100	        factory = msg.sender;
101	        self = address(this);
102	    }
103	
104	    modifier nonReentrant() {
105	        if (locked) revert Locked();
106	        locked = true;
107	        _;
108	        locked = false;
109	    }
110	
111	    /// @dev Refuses entry while a money path holds the lock; does not take it. A configuration change
112	    /// landing between two rows of `distribute` would pay the rest from a table nobody has seen.
113	    modifier notLocked() {
114	        if (locked) revert Locked();
115	        _;
116	    }
117	
118	    /// @dev The timelock reaches state only through a self-call, so every mutator is `onlySelf`.
119	    modifier onlySelf() {
120	        if (msg.sender != address(this)) revert Unauthorized();
121	        _;
122	    }
123	
124	    /// @notice Initialise a clone. Callable once, by whoever deployed the implementation.
125	    function init(address owner_, uint32 delay_, string calldata description_, Beneficiary[] calldata table_)
126	        external
127	        payable
128	    {
129	        if (msg.sender != factory || _table.length != 0) revert Unauthorized();
130	        owner = owner_;
131	        delay = delay_;
132	        description = description_;
133	        _set(table_);
134	    }
135	
136	    /// @dev Must run under a 2,300-gas `transfer` stipend, so it does nothing but the guard and the log.
137	    receive() external payable {
138	        if (address(this) == self) revert Unauthorized();
139	        emit Received(msg.sender, msg.value);
140	    }
141	
142	    /// @notice Split everything not already escrowed between the table, in table order.
143	    /// @param token The ERC-20 to split, or `address(0)` for ETH.
144	    function distribute(address token) external nonReentrant {
145	        uint256 amount = _balance(token) - reserved[token];
146	        if (amount == 0) revert NothingToDo();
147	
148	        uint256 n = _table.length;
149	        uint256 paid;
150	        for (uint256 i; i < n; ++i) {
151	            Beneficiary storage b = _table[i];
152	            // The last row takes the remainder, so the shares always sum to `amount`.
153	            uint256 share = i + 1 == n ? amount - paid : (uint256(b.bps) * amount) / BPS_TOTAL;
154	            paid += share;
155	            address account = b.account;
156	            (bool ok,) = _push(token, account, share, false);
157	            if (!ok) {
158	                escrowed[token][account] += share;
159	                reserved[token] += share;
160	                emit Escrowed(token, account, share);
161	            }
162	        }
163	        emit Distributed(token, amount);
164	    }
165	
166	    /// @notice Retry the escrowed amount for one account. Reverts if the retry fails, leaving the escrow.
167	    function release(address token, address account) external nonReentrant {
168	        uint256 amount = escrowed[token][account];
169	        if (amount == 0) revert NothingToDo();
170	
171	        escrowed[token][account] = 0;
172	        reserved[token] -= amount;
173	        (bool ok, bytes memory data) = _push(token, account, amount, true);
174	        // A word or less is the bare `false` of a non-reverting token, empty revert data, or an
175	        // argument-less custom error: no reason worth bubbling, so name the failure instead
176	        // (decision 24). Anything longer carries its own reason and keeps it.
177	        if (!ok) {
178	            if (data.length <= 32) revert ReleaseFailed(token);
179	            _bubble(data);
180	        }
181	        emit Released(token, account, amount);
182	    }
183	
184	    /// @notice Queue a self-call, or run it now when `delay` is zero. Refused while `distribute` or
185	    /// `release` is running.
186	    /// @param action Calldata for one of this contract's `onlySelf` functions.
187	    function propose(bytes calldata action) external notLocked returns (bytes32 hash) {
188	        if (msg.sender != owner) revert NotOwner();
189	
190	        uint32 n = ++nonce;
191	        hash = keccak256(abi.encode(action, n));
192	        uint32 d = delay;
193	        if (d == 0) {
194	            emit Queued(hash, n, block.timestamp, action);
195	            _selfCall(action);
196	            emit Applied(hash);
197	        } else {
198	            uint256 eta = block.timestamp + d;
199	            queued[hash] = eta;
200	            _pendingIndex[hash] = _pending.length + 1;
201	            _pending.push(Pending({hash: hash, eta: eta, action: action}));
202	            emit Queued(hash, n, eta, action);
203	        }
204	    }
205	
206	    /// @notice Run a queued action once its eta has passed. A failing action stays queued for a retry.
207	    /// Refused while `distribute` or `release` is running.
208	    function applyQueued(bytes calldata action, uint32 nonce_) external notLocked {
209	        bytes32 hash = keccak256(abi.encode(action, nonce_));
210	        uint256 eta = queued[hash];
211	        // A timelock is a timestamp comparison; a validator's few seconds of drift is not the threat.
212	        // forge-lint: disable-next-line(block-timestamp)
213	        if (eta == 0 || block.timestamp < eta) revert NotReady(eta);
214	
215	        delete queued[hash];
216	        _remove(hash);
217	        _selfCall(action);
218	        emit Applied(hash);
219	    }
220	
221	    /// @notice Drop a queued action. Immediate: the delay guards applying, not cancelling.
222	    function cancel(bytes32 hash) external {
223	        if (msg.sender != owner) revert NotOwner();
224	        if (queued[hash] == 0) revert NothingToDo();
225	
226	        delete queued[hash];
227	        _remove(hash);
228	        emit Cancelled(hash);
229	    }
230	
231	    function setBeneficiaries(Beneficiary[] calldata table_) external onlySelf {
232	        _set(table_);
233	    }
234	
235	    function setDescription(string calldata description_) external onlySelf {
236	        description = description_;
237	    }
238	
239	    function setDelay(uint32 delay_) external onlySelf {
240	        delay = delay_;
241	    }
242	
243	    /// @notice Name the next owner, who must call `acceptOwnership()` before anything changes; until
244	    /// then the current owner keeps every power. `address(0)` renounces at once — nothing can be
245	    /// proposed or cancelled again, and drops every queued action — and drops any pending transfer
246	    /// with it. Naming the current owner withdraws a pending transfer.
247	    function transferOwnership(address owner_) external onlySelf {
248	        if (owner_ == address(0)) {
249	            owner = address(0);
250	            pendingOwner = address(0);
251	            _clearQueue();
252	            return;
253	        }
254	        pendingOwner = owner_ == owner ? address(0) : owner_;
255	    }
256	
257	    /// @notice Take ownership after the owner named you with `transferOwnership`, and drops every
258	    /// action the previous owner queued.
259	    function acceptOwnership() external {
260	        if (msg.sender != pendingOwner) revert Unauthorized();
261	
262	        emit OwnershipTransferred(owner, msg.sender);
263	        owner = msg.sender;
264	        pendingOwner = address(0);
265	        _clearQueue();
266	    }
267	
268	    /// @notice Everything a reader needs in one call.
269	    function snapshot() external view returns (Snapshot memory) {
270	        return Snapshot({
271	            owner: owner, delay: delay, nonce: nonce, description: description, table: _table, pending: _pending
272	        });
273	    }
274	
275	    /// @dev Not `table()`: forge reserves the `table` prefix for table tests and fails the suite.
276	    function beneficiaries() external view returns (Beneficiary[] memory) {
277	        return _table;
278	    }
279	
280	    function pendingCount() external view returns (uint256) {
281	        return _pending.length;
282	    }
283	
284	    /// @dev Ascending accounts make duplicates impossible and keep the first row above `address(0)`.
285	    function _set(Beneficiary[] calldata table_) private {
286	        uint256 n = table_.length;
287	        if (n == 0 || n > MAX_BENEFICIARIES) revert BadTable();
288	
289	        delete _table;
290	        uint256 sum;
291	        address prev;
292	        for (uint256 i; i < n; ++i) {
293	            Beneficiary calldata b = table_[i];
294	            if (b.bps == 0 || b.account <= prev) revert BadTable();
295	            prev = b.account;
296	            sum += b.bps;
297	            _table.push(b);
298	        }
299	        if (sum != BPS_TOTAL) revert BadTable();
300	    }
301	
302	    /// @dev Drops every queued action, newest first, emitting `Cancelled` for each so a log reader's
303	    /// pending list empties the way it would have by hand. Runs on a handover and on a renounce:
304	    /// what the previous owner queued was queued under an authority that no longer exists.
305	    function _clearQueue() private {
306	        uint256 n = _pending.length;
307	        while (n > 0) {
308	            bytes32 hash = _pending[--n].hash;
309	            delete queued[hash];
310	            delete _pendingIndex[hash];
311	            _pending.pop();
312	            emit Cancelled(hash);
313	        }
314	    }
315	
316	    /// @dev Swap-and-pop, so `_pending` stays iterable and the surviving order is stable otherwise.
317	    function _remove(bytes32 hash) private {
318	        uint256 i = _pendingIndex[hash];
319	        if (i == 0) return;
320	
321	        uint256 last = _pending.length;
322	        if (i != last) {
323	            Pending storage moved = _pending[last - 1];
324	            _pending[i - 1] = moved;
325	            _pendingIndex[moved.hash] = i;
326	        }
327	        _pending.pop();
328	        delete _pendingIndex[hash];
329	    }
330	
331	    function _selfCall(bytes calldata action) private {
332	        (bool ok, bytes memory data) = address(this).call(action);
333	        if (!ok) _bubble(data);
334	    }
335	
336	    /// @dev A token with no code returns nothing here, which does not decode — so it fails.
337	    function _balance(address token) private view returns (uint256) {
338	        if (token == address(0)) return address(this).balance;
339	
340	        (bool ok, bytes memory data) = token.staticcall(abi.encodeWithSelector(BALANCE_OF, address(this)));
341	        if (!ok) _bubble(data);
342	        return abi.decode(data, (uint256));
343	    }
344	
345	    /// @dev ETH is capped so one hostile recipient cannot burn the whole distribution; an ERC-20 push
346	    /// is bounded by the token. A no-return token (mainnet USDT) counts as success; anything else must
347	    /// answer with a word equal to one, decoded as a `uint256` so hostile return data cannot revert here.
348	    ///
349	    /// `keepData` buys the ETH branch's return data. `distribute` passes false and calls with a
350	    /// zero-length output area, so a recipient reverting with megabytes costs it one `RETURNDATASIZE`
351	    /// it never reads instead of the memory to hold them — unbounded copying inside the loop broke the
352	    /// half-block property decision 27 rests on at about eleven hostile rows. `release` passes true,
353	    /// because decision 24 bubbles a reason longer than a word and cannot name one it did not copy.
354	    /// The ERC-20 branch ignores the flag: it needs the return word below, and the token is the one
355	    /// `distribute(token)` was called with, so a hostile token's return data costs only the caller who
356	    /// named it.
357	    function _push(address token, address to, uint256 amount, bool keepData)
358	        private
359	        returns (bool ok, bytes memory data)
360	    {
361	        if (token == address(0)) {
362	            if (keepData) {
363	                (ok, data) = to.call{value: amount, gas: PUSH_GAS}("");
364	            } else {
365	                uint256 gasCap = PUSH_GAS;
366	                assembly ("memory-safe") {
367	                    ok := call(gasCap, to, amount, 0, 0, 0, 0)
368	                }
369	            }
370	            return (ok, data);
371	        }
372	        (ok, data) = token.call(abi.encodeWithSelector(TRANSFER, to, amount));
373	        ok = ok && (data.length == 0 || (data.length >= 32 && abi.decode(data, (uint256)) == 1));
374	    }
375	
376	    function _bubble(bytes memory data) private pure {
377	        assembly ("memory-safe") {
378	            revert(add(data, 0x20), mload(data))
379	        }
380	    }
381	}
