383	/// @notice Deploys `Distribution` clones to an address that depends on this factory and a salt alone.
384	/// @dev No `receive` and no `fallback`, so ETH sent to the factory itself reverts; the implementation
385	/// rejects it too. Clones are PUSH0 minimal proxies placed with CREATE2, so the same factory reaches
386	/// the same clone address on every chain.
387	contract DistributionFactory {
388	    event Created(address indexed distribution, address indexed owner);
389	
390	    error DeploymentFailed();
391	    error SaltDoesNotStartWith();
392	
393	    /// @dev Deployed by the factory, so `Distribution.factory` is this contract on every clone.
394	    address public immutable implementation = address(new Distribution{salt: bytes32(0)}());
395	
396	    /// @notice Deploy and initialise a clone at `predict(salt)`.
397	    /// @param salt Its top 20 bytes must equal `msg.sender`. `msg.value` rides the CREATE2, so a
398	    /// deposit lands in the clone without a `Received` log.
399	    /// @dev Three properties the dapp has to know about this address:
400	    /// 1. It depends on this factory and `salt` only — not on the owner, delay, description or table.
401	    ///    So the sender fixes the address; the owner does not enter it. One EOA calls `create` with
402	    ///    the same salt on every chain and passes the vault as `owner_`, and the clone is owned by
403	    ///    that vault from its first block at one address, with no ownership transfer ever needed.
404	    ///    Each chain is a separate contract: transferring ownership on one changes neither the salt
405	    ///    nor any other chain, so the deploying key never needs to own anything.
406	    /// 2. A second `create` with a used salt burns the whole gas limit before `DeploymentFailed`: a
407	    ///    CREATE2 collision consumes every unit forwarded to it. Read `predict(salt)` with
408	    ///    `eth_getCode` first and refuse a non-empty answer.
409	    /// 3. Same-address-everywhere is this factory's address, not a clone's claim on its own. The
410	    ///    factory is nonce-addressed where it is deployed; a byte-identical deploy through a
411	    ///    deterministic deployer is a later milestone's one-way door.
412	    function create(
413	        address owner_,
414	        uint32 delay_,
415	        string calldata description_,
416	        Distribution.Beneficiary[] calldata table_,
417	        bytes32 salt
418	    ) external payable returns (address distribution) {
419	        address impl = implementation;
420	        uint256 prefix = uint256(salt) >> 96;
421	        if (prefix != uint256(uint160(msg.sender))) revert SaltDoesNotStartWith();
422	
423	        // The PUSH0 minimal-proxy init code, byte for byte as solady's `LibClone.initCode_PUSH0`
424	        // writes it. The two `mstore`s at 0x24 overlap the free memory pointer and restore it.
425	        assembly ("memory-safe") {
426	            mstore(0x24, 0x5af43d5f5f3e6029573d5ffd5b3d5ff3)
427	            mstore(0x14, impl)
428	            mstore(0x00, 0x602d5f8160095f39f35f5f365f5f37365f73)
429	            distribution := create2(callvalue(), 0x0e, 0x36, salt)
430	            if iszero(distribution) {
431	                mstore(0x00, 0x30116425) // DeploymentFailed()
432	                revert(0x1c, 0x04)
433	            }
434	            mstore(0x24, 0)
435	        }
436	        Distribution(payable(distribution)).init(owner_, delay_, description_, table_);
437	        emit Created(distribution, owner_);
438	    }
439	
440	    /// @notice The address `create(..., salt)` would reach.
441	    /// @dev No prefix check: the dapp predicts before it knows who will send.
442	    function predict(bytes32 salt) external view returns (address) {
443	        address impl = implementation;
444	        bytes32 initCodeHash;
445	        assembly ("memory-safe") {
446	            mstore(0x24, 0x5af43d5f5f3e6029573d5ffd5b3d5ff3)
447	            mstore(0x14, impl)
448	            mstore(0x00, 0x602d5f8160095f39f35f5f365f5f37365f73)
449	            initCodeHash := keccak256(0x0e, 0x36)
450	            mstore(0x24, 0)
451	        }
452	        return address(uint160(uint256(keccak256(abi.encodePacked(hex"ff", address(this), salt, initCodeHash)))));
453	    }
454	}
