461	// SPDX-License-Identifier: MIT
462	pragma solidity ^0.8.26;
463	
464	import {Ownable} from "solady/auth/Ownable.sol";
465	import {SSTORE2} from "solady/utils/SSTORE2.sol";
466	import {Base64} from "solady/utils/Base64.sol";
467	
468	/// @title App
469	/// @notice The dapp and its embeddable widget, hosted by this contract.
470	///         ERC-8244: `html()` returns the whole document.
471	///         ERC-5219 / ERC-6944: `request()` serves "/" with a text/html header so web3:// gateways
472	///         render it at the root, and `request(["widget.js"])` the widget as application/javascript.
473	/// @dev Two resources, two pointer lists: `chunks` for the dapp and `widgetChunks` for the widget.
474	///      Each document lives in SSTORE2 chunks, concatenated at read time. If `gzipped`, `html()` wraps
475	///      the base64 payload in a bootstrap that inflates it client-side with DecompressionStream. The
476	///      widget is served raw and never wrapped: a `<script src="widget.js">` fetched through a gateway
477	///      must be plain JavaScript, and the bootstrap is an HTML document a script tag cannot run.
478	///      `lock()` freezes both lists; it requires the dapp and does not require a widget.
479	contract App is Ownable {
480	    struct KeyValue {
481	        string key;
482	        string value;
483	    }
484	
485	    address[] public chunks;
486	    address[] public widgetChunks;
487	    bool public gzipped;
488	    bool public locked;
489	    string public version;
490	
491	    event ChunksSet(uint256 count, bool gzipped);
492	    event WidgetChunksSet(uint256 count);
493	    event VersionSet(string version);
494	    event AppLocked();
495	
496	    error Locked();
497	    /// @dev A pointer holding no code. `SSTORE2.read` on one expands memory past any block gas limit,
498	    ///      so `html()` and `request()` would run out of gas for every caller.
499	    error CodelessChunk(address ptr);
500	    /// @dev No pointers at all: `html()` would return an empty document.
501	    error EmptyDocument();
502	
503	    constructor(address owner_, string memory version_) {
504	        _initializeOwner(owner_);
505	        version = version_;
506	    }
507	
508	    /// @dev Every byte of the bootstrap is load-bearing and `test_gzipBootstrap` pins all of it.
509	    ///      It swaps the document in with `DOMParser`, not `document.open()`, which orphans an
510	    ///      extension wallet's content script. `DOMParser` marks the scripts it builds non-executable,
511	    ///      so each is re-created; `replaceWith` runs an inline script synchronously on insertion,
512	    ///      which preserves document order for inline, attribute-free scripts and nothing else.
513	    function html() public view returns (string memory) {
514	        bytes memory doc = _raw(chunks);
515	        if (!gzipped) return string(doc);
516	        return string.concat(
517	            '<!DOCTYPE html><html><head><meta charset="utf-8"><title>app</title></head><body><script>',
518	            '(async()=>{const b=atob("',
519	            Base64.encode(doc),
520	            '");',
521	            "const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);",
522	            "const t=await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).text();",
523	            "const d=new DOMParser().parseFromString(t,'text/html');",
524	            "document.replaceChild(document.importNode(d.documentElement,true),document.documentElement);",
525	            "for(const s of[...document.querySelectorAll('script')]){const n=document.createElement('script');",
526	            "for(const a of s.attributes)n.setAttribute(a.name,a.value);",
527	            "n.textContent=s.textContent;s.replaceWith(n);}})();",
528	            "</script></body></html>"
529	        );
530	    }
531	
532	    /// @notice The widget, as stored: the raw concatenation of `widgetChunks`, never wrapped.
533	    function widget() public view returns (string memory) {
534	        return string(_raw(widgetChunks));
535	    }
536	
537	    function resolveMode() external pure returns (bytes32) {
538	        return "5219";
539	    }
540	
541	    /// @dev An empty `widgetChunks` answers "widget.js" with the same 404 as any unknown path, so an
542	    ///      `App` carrying the dapp and no widget is a complete site rather than a broken one.
543	    function request(string[] memory resource, KeyValue[] memory)
544	        external
545	        view
546	        returns (uint16 statusCode, string memory body, KeyValue[] memory headers)
