424	        // writes it. The two `mstore`s at 0x24 overlap the free memory pointer and restore it.
425	        assembly ("memory-safe") {
426	            mstore(0x24, 0x5af43d5f5f3e6029573d5ffd5b3d5ff3)
427	            mstore(0x14, impl)
428	            mstore(0x00, 0x602d5f8160095f39f35f5f365f5f37365f73)
429	            distribution := create2(callvalue(), 0x0e, 0x36, salt)
430	            if iszero(distribution) {
431	                mstore(0x00, 0x30116425) // DeploymentFailed()
432	                revert(0x1c, 0x04)
433	            }
434	            mstore(0x24, 0)
435	        }
436	        Distribution(payable(distribution)).init(owner_, delay_, description_, table_);
437	        emit Created(distribution, owner_);
438	    }
