440	    /// @notice The address `create(..., salt)` would reach.
441	    /// @dev No prefix check: the dapp predicts before it knows who will send.
442	    function predict(bytes32 salt) external view returns (address) {
443	        address impl = implementation;
444	        bytes32 initCodeHash;
445	        assembly ("memory-safe") {
446	            mstore(0x24, 0x5af43d5f5f3e6029573d5ffd5b3d5ff3)
447	            mstore(0x14, impl)
448	            mstore(0x00, 0x602d5f8160095f39f35f5f365f5f37365f73)
449	            initCodeHash := keccak256(0x0e, 0x36)
450	            mstore(0x24, 0)
451	        }
452	        return address(uint160(uint256(keccak256(abi.encodePacked(hex"ff", address(this), salt, initCodeHash)))));
453	    }
